/**
 * Normalises any header value sent by a component into a consistent shape.
 *
 * Supported input forms:
 *   - null / undefined  → { primary: "", secondary: "", jsx: "" }
 *   - string            → { primary: header, secondary: "", jsx: "" }
 *   - { primary, secondary? } object → mapped fields
 *   - JSX element / anything else   → { primary: "", secondary: "", jsx: header }
 *
 * @param {*} header - Raw header value received from an iframe message
 * @returns {{ primary: string, secondary: string, jsx: * }}
 */
export function formatHeaderToTitle(header) {
    if (!header) {
        return { primary: "", secondary: "", jsx: "" };
    }

    // Plain string
    if (typeof header === "string") {
        return { primary: header, secondary: "", jsx: "" };
    }

    // Object with a primary property
    if (typeof header === "object" && !("$$typeof" in header) && "primary" in header) {
        return {
            primary: header.primary || "",
            secondary: header.secondary?.text || "",
            jsx: "",
        };
    }

    // JSX element or anything else
    return { primary: "", secondary: "", jsx: header };
}
