import React from 'react';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import InputBase from '@mui/material/InputBase';
import Box from '@mui/material/Box';
import { alpha, useTheme } from '@mui/material/styles';
import HDUIOptions from './hDUIOptions';
import { ProfileHeaderMenu } from './ProfileWrapper';
import { useMediaQuery } from '@mui/material';


const KEYCODES = {
  ENTER: 13,
};

export default function HDAppBar(props) {
  const theme = useTheme();
  const { componentMargin, isFullScreen, componentName, title } = props;

  const onKeyDown = (event) => {
    if (event.keyCode === KEYCODES.ENTER) {
      let queryTerm = event.target.value.trim();
      if (queryTerm !== '') {
        props.onSearch(queryTerm);
        event.preventDefault();
      }
    }
  };

  // showInitialToolbar = false when the iframe has sent a title (primary, secondary, or jsx)
  const hasTitle = (title?.primary || title?.secondary || title?.jsx) && isFullScreen;
  const showInitialToolbar = !hasTitle;
  const isLgUp = useMediaQuery(theme.breakpoints.up('lg'));
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const showTopUIOptions =
    (showInitialToolbar &&
      isLgUp) ||
    props.UIOptions.isMobile;

  const SearchBar = ({ width, compact, onKeyDown, query }) => {
    const [value, setValue] = React.useState(query || '');

    React.useEffect(() => {
      setValue(query || '');
    }, [query]);


    return (
      <Box sx={{ width: width || '100%', maxWidth: width ? undefined : 600 }}>
        <Box
          sx={(theme) => ({
            display: "flex",
            alignItems: "center",
            borderRadius: "24px",
            border: `1px solid ${theme.palette.divider}`,
            backgroundColor: theme.palette.background.paper,
            boxShadow: theme.shadows[3],
            px: 2,
            py: compact ? 0.3 : 0.5,
            transition: "all 0.2s ease-in-out",
            "&:hover": {
              boxShadow:
                theme.palette.mode === "light"
                  ? "0 2px 6px rgba(0,0,0,0.12)"
                  : "0 2px 6px rgba(255,255,255,0.12)",
              borderColor: theme.palette.grey[400],
            },
            "&:focus-within": {
              boxShadow: `0 0 0 2px ${alpha(theme.palette.primary.main, 0.2)}`,
              borderColor: theme.palette.primary.main,
            },
          })}
        >
          <InputBase
            placeholder="Search…"
            value={value}
            onChange={(e) => setValue(e.target.value)}
            fullWidth
            sx={{
              ml: 1,
            }}
            inputProps={{ onKeyDown }}
          />
        </Box>
      </Box>
    )
  }

  const uiOptionsSx = {
    position: 'fixed',
    zIndex: 1200,
    ...(showTopUIOptions
      ? {
        top: 8,
        right: isFullScreen ? 48 : 8,
      }
      : {
        bottom: 0,
        left: 0,
        width: '100%',
        px: 1,
      }),
  };

  return (
    <Box>
      {/* UIOptions */}
      {
        <Box sx={uiOptionsSx}>
          <HDUIOptions
            isFullScreen={isFullScreen}
            UIOptions={props.UIOptions}
            newUIOptions={props.newUIOptions}
            showTopUIOptions={showTopUIOptions}
          />
        </Box>
      }

      <AppBar
        position="static"
        elevation={0}
        sx={{
          backgroundColor: (theme) => theme.palette.background.default,
          color: (theme) => theme.palette.text.primary,
          height: 48,
          zIndex: 1,
        }}
      >
        <Toolbar
          disableGutters
          variant="dense"
          sx={{
            minHeight: '48px !important',
            px: showInitialToolbar
              ? 1
              : props.componentLoaded && isFullScreen
                ? 0
                : 2,
            display: "flex",
            alignItems: "center",
            gap: showInitialToolbar ? 0 : 2,
            position: 'relative',
          }}
        >
          {/* Logo */}
          {props.UIOptions.format !== "mobile" && (
            <Typography
              variant="body1"
              noWrap
              sx={{
                color: (theme) => theme.palette.primary.main,
                ml: 1,
                mr: 2,
              }}
            >
              hyperDart
            </Typography>
          )}
          {showInitialToolbar ? (
            <>

              {/* Search */}
              <Box sx={{ flexGrow: 1 }}>
                <SearchBar
                  query={props.query}
                  compact={props.UIOptions.format === "mobile"}
                  onKeyDown={onKeyDown}
                />
              </Box>
            </>
          ) : (
            <>
              {/* Title layer: absolute center on mobile, flex center on desktop */}
              <Box
                sx={{
                  ...(isMobile ? {
                    position: 'absolute',
                    left: 0,
                    right: 0,
                    pointerEvents: 'none',
                  } : {
                    flexGrow: 1,
                  }),
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  px: 2,
                }}
              >
                <Box sx={{ pointerEvents: 'auto', display: 'flex', justifyContent: 'center' }}>
                  {title?.jsx
                    ? title.jsx
                    : (
                      <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                        {title?.primary && (
                          <Typography variant="subtitle2" noWrap sx={{ fontWeight: 600, lineHeight: 1.2 }}>
                            {title.primary}
                          </Typography>
                        )}
                        {title?.secondary && (
                          <Typography variant="caption" noWrap sx={{ color: 'text.secondary', lineHeight: 1.2 }}>
                            {title.secondary}
                          </Typography>
                        )}
                      </Box>
                    )
                  }
                </Box>
              </Box>

              {!isMobile && (
                <SearchBar
                  width={{ xs: "100%", sm: 450, md: 450 }}
                  compact
                  onKeyDown={onKeyDown}
                  query={props.query}
                />
              )}
            </>
          )}
          {/* 3-dots menu — always visible on the right in fullscreen */}
          {isFullScreen && (
            <Box sx={{ ml: 'auto', pr: 1 }}>
              <ProfileHeaderMenu componentName={componentName} />
            </Box>
          )}
        </Toolbar>
      </AppBar>
    </Box>
  );

}
