import React, { Component } from 'react';
const FRAME_WIDTH = {
	sidebar: "400px",
	mainline: "720px",
	fullscreen: "100%",
	mobile: "420px"
}
export default class HDIFrame extends Component {

	constructor(props) {
		super(props);
		this.iFrame = null
		this.state = {
			iFrameHeight: 0,
			fullScreen: false,
			// showCloseButton: false,
			navigatedViaRoute: false
		}
		this.actionQueue = [];
		this.isProcessingQueue = false;
		this.setIFrame = iframe => {
			this.iFrame = iframe
		}
		this.resizeTimer = null
		this.iFrameLoaded = this.iFrameLoaded.bind(this)
		this.handleMessage = this.handleMessage.bind(this)
		window.addEventListener("message", this.handleMessage)
	}

	enqueueAction = async (action) => {
		// Rate-limiting: prevent memory exhaustion if the iFrame
		// floods the parent with messages. Limits backlog to 4 pending actions.
		if (this.actionQueue.length >= 5) {
			console.warn("Action queue is full, rejecting action");
			return;
		}

		this.actionQueue.push(action);

		// If already processing, the current loop will pick up the new action
		if (this.isProcessingQueue) return;

		this.isProcessingQueue = true;
		try {
			while (this.actionQueue.length > 0) {
				const currentAction = this.actionQueue[0];
				try {
					await currentAction();
				} catch (err) {
					console.error("Action execution failed in HDIFrame queue:", err);
				}
				this.actionQueue.shift();
			}
		} finally {
			this.isProcessingQueue = false;
		}
	}

	handleMessage = async (e) => {
		const component = this.props?.UIOptions?.sandbox ? this.props?.config?.name : this.props.searchData?.[0]?.component;
		if (!this.iFrame || this.iFrame.contentWindow !== e.source) {
			return;
		}
		if (e.data.type === 'reactHydrated') {
			this.iFrameLoaded();
		}
		if (e.data.type === 'resizeIframe') {
			clearTimeout(this.resizeTimer);
			this.resizeTimer = setTimeout(() => {
				const height = e.data.height > 0 ? e.data.height + 30 : e.data.height;
				this.setState({ iFrameHeight: height }, () => {
					if (this.props.onHeightChange) {
						this.props.onHeightChange(height);
					}
				});
			}, 100);
		}
		if (e.data.type === 'switchFullScreen') {
			this.enqueueAction(async () => {
				this.handleScreenChange(e);
			});
		}
		if (e.data.type === 'searchQuery' && e.data.query && this.props.callInitiateSearch) {
			this.props.callInitiateSearch({ title: e.data.query });
		}
		if (e.data.type === 'setWebsearchHeader' && this.props.WebSearchHeaderHandler) {
			this.props.WebSearchHeaderHandler(e.data.header);
		}
		if (e.data.type === 'loadAiGeneratedResponse' && this.props.loadAiGeneratedResponse) {
			const payload = e.data?.payload;
			const requestId = e.data?.requestId;

			try {
				const result = await this.props.loadAiGeneratedResponse(payload);
				e.source.postMessage({
					type: 'loadAiGeneratedResponseResult',
					response: result,
					requestId
				}, e.origin);

			} catch (error) {
				e.source.postMessage({
					type: 'loadAiGeneratedResponseResult',
					error: error.message || 'Something went wrong',
					requestId
				}, e.origin);
			}
		}

		if (e.data.type === 'searchShortcutPressed' && this.props.onSearchShortcut) {
			this.props.onSearchShortcut({
				key: e.data.event?.key,
				code: e.data.event?.code,
				preventDefault: () => { }
			});
		}
		if (e.data.type === 'updateComponentPath') {
			const path = e.data.componentPath;
			if (path) {
				this.enqueueAction(async () => {
					this.updateComponentPath(path, component);
				});
			}
		};
		if (e.data.type === 'componentLoaded' && this.props.componentLoaded) {
			this.props.componentLoaded()
		}

		if (e.data.type === 'unload' && this.props.unloadStandalone) {
			this.props.unloadStandalone(e.data.message);
		}

		// if (e.data.type === 'showClose') {
		// 	this.setState({ showCloseButton: true })
		// }


	}

	handleScreenChange = (e) => {
		const { location, history, navigate } = this.props;
		const component = this.props?.UIOptions?.sandbox ? this.props?.config?.name : this.props.searchData?.[0]?.component;
		this.switchFullScreen(e.data.fullScreen);

		// Reading from window.location.search instead of this.props.location.search here
		// This fixes race conditions if multiple message events from the iframe attempt to modify the location.
		// `props.location` needs React to reconcile the history push before updating, 
		// but `window.location` immediately reflects history changes in the browser.
		const search = window.location.search;
		const searchParams = new URLSearchParams(search);
		// Add or update query parameters
		const fullScreenComponent = this.getFullScreenComponent();
		if (e.data.fullScreen && fullScreenComponent !== component) {
			searchParams.set('fullscreen', component);
		} else {
			searchParams.delete('fullscreen');
		}

		if (!e.data.fullScreen || (e.data.fullScreen && fullScreenComponent !== component)) {
			if (location && location.pathname) {
				const newPath = `${location.pathname}?${searchParams.toString()}`;
				if (e.data.navigatedViaRoute) {
					// setting navigatedViaRoute to true if component switches to fullscreen with a route change inside component
					// This lets us know that with this fullscreen switch there are 2 pushes in history stach, one from component end for path change other from below to add fullscreen to query params
					this.setState({
						navigatedViaRoute: true
					})

				}

				// Even when there is a subsequent push inside the component (signaled by navigatedViaRoute), 
				// we must use history.push here rather than history.replace.
				// Because the parent and iframe use separate BrowserRouters, if we used replace, 
				// the parent history instance wouldn't record a new entry for the fullscreen state change. 
				// This would cause the back button to fail in closing fullscreen, 
				// as there would be no push entry in the parent history to pop back from.
				if (history) {
					history.push(newPath);
				} else if (navigate) {
					navigate(newPath);
				}


			}
		}
	}


	getComponentPath = (component) => {
		const search = this.props && this.props.location && this.props.location.search;

		// Check if search is present and not an empty string
		if (!search) {
			return null;
		}

		// Proceed only if search exists
		const params = new URLSearchParams(search);
		const componentPaths = params.getAll('component');
		const componentPath = componentPaths && componentPaths.length > 0 ? componentPaths.find(value => {
			return value.includes(component)
		}) : null

		return componentPath;

	}

	updateComponentPath = (path, component) => {
		const { location, history, navigate } = this.props;

		// Reading from window.location.search instead of this.props.location.search here
		// This fixes race conditions if multiple message events from the iframe attempt to modify the location.
		// `props.location` needs React to reconcile the history push before updating, 
		// but `window.location` immediately reflects history changes in the browser.
		const search = window.location.search;
		const searchParams = new URLSearchParams(search);


		const existingPaths = searchParams.getAll('component');
		let updatedExistingPaths = [];
		let pathReplaced = false;
		existingPaths && existingPaths.forEach(item => {
			if (item.includes(component)) {
				pathReplaced = true;
				updatedExistingPaths.push(path);
			} else {
				updatedExistingPaths.push(item);
			}
		})

		if (!pathReplaced) {
			updatedExistingPaths.push(path);
		}
		searchParams.delete('component');

		updatedExistingPaths.forEach(path => {
			searchParams.append('component', path);
		});
		if (location && location.pathname) {
			const newPath = `${location.pathname}?${searchParams.toString()}`;
			if (history) {
				history.replace(newPath);
			} else if (navigate) {
				navigate(newPath, { replace: true });
			}
		}
	}


	getFullScreenComponent = () => {
		const search = this.props && this.props.location && this.props.location.search;
		if (!search) {
			return null;
		}
		let params = new URLSearchParams(search);
		let fullScreenComponent = decodeURIComponent(params.get('fullscreen'));
		return fullScreenComponent !== 'null' ? fullScreenComponent : null;
	}




	switchFullScreen(fullScreenMode = true) {
		if (fullScreenMode !== this.state.fullScreen) {
			this.setState({ fullScreen: fullScreenMode },
				() => this.sendSearchDataToIFrame()
			);
			if (this.props.onFullScreenChange) {
				this.props.onFullScreenChange(fullScreenMode);
			}
		}
		if (!fullScreenMode && this.props.onCloseFullScreen)
			this.props.onCloseFullScreen();


	}


	sendSearchDataToIFrame(path = null) {
		if (this.iFrame) {
			this.iFrame.contentWindow.postMessage({
				type: "dataRefresh",
				searchData: [
					{
						...this.props.searchData[0],
						componentPath: path
					},
					...this.props.searchData.slice(1)
				],
				UIOptions: {
					...this.props.UIOptions,
					format: this.state.fullScreen ? 'fullscreen' : this.props.UIOptions?.format,
				}
			}, '*')
		}
	}

	iFrameLoaded() {
		const component = this.props?.UIOptions?.sandbox ? this.props?.config?.name : this.props.searchData?.[0]?.component;
		const componentPath = this.getComponentPath(component);
		const fullScreenComponent = this.getFullScreenComponent();
		if (fullScreenComponent && component === fullScreenComponent && !this.state.fullScreen) {
			this.setState({ fullScreen: true }, () => {
				this.sendComponentPathToIframe(componentPath)
			})
			if (this.props.onFullScreenChange) this.props.onFullScreenChange(true);
		} else {
			this.sendComponentPathToIframe(componentPath)
		}



	}

	sendComponentPathToIframe = (componentPath) => {
		if (componentPath) {
			this.sendSearchDataToIFrame(componentPath)
		} else {
			this.sendSearchDataToIFrame()
		}
	}

	componentDidMount() {
		if (this.props?.onMount) {
			this.props.onMount()
		}
	}


	componentDidUpdate(prevProps, prevState) {
		const prevContext = {
			query: prevProps.searchData?.[0]?.query,
			theme: prevProps.UIOptions?.themeName,
			format: prevProps.UIOptions?.format,
		};

		const currentContext = {
			query: this.props.searchData?.[0]?.query,
			theme: this.props.UIOptions?.themeName,
			format: this.props.UIOptions?.format,
		};

		const hasChanged =
			(currentContext.query &&
				currentContext.query !== prevContext.query) ||
			prevContext.theme !== currentContext.theme ||
			prevContext.format !== currentContext.format;

		if (hasChanged) {
			this.sendSearchDataToIFrame();
		}

		const prevSearch = prevProps.location && prevProps.location.search;
		const currentSearch = this.props.location && this.props.location.search;


		const prevParams = new URLSearchParams(prevSearch);
		const currentParams = new URLSearchParams(currentSearch);
		let currentQueryFromParams = decodeURIComponent(currentParams.get('q'));
		let prevQueryFromParams = decodeURIComponent(prevParams.get('q'));

		const prevFullScreenComponent = decodeURIComponent(prevParams.get('fullscreen'));
		const currentFullScreenComponent = decodeURIComponent(currentParams.get('fullscreen'));

		if (prevFullScreenComponent !== currentFullScreenComponent && this.state.fullScreen) {
			// This condition triggers when we pressing back button and fullscreen closes
			if ((!currentFullScreenComponent || currentFullScreenComponent === 'null') && prevFullScreenComponent && prevFullScreenComponent !== 'null' && currentQueryFromParams === prevQueryFromParams) {
				this.switchFullScreen(false);
				// If there were 2 pushes in history stack while going to full screen we need to go back twice , hence another history.goBack()
				if (this.state.navigatedViaRoute) {
					this.setState({ navigatedViaRoute: false }, () => {
						if (this.props.history) {
							this.props.history.goBack();
						} else if (this.props.navigate) {
							this.props.navigate(-1);
						}

					})
				}
			}
		}

	}

	componentWillUnmount() {
		clearTimeout(this.resizeTimer);
		document.body.style.overflow = 'unset';
		window.removeEventListener('message', this.handleMessage);
	}

	render() {
		const { config, UIOptions, baseURL } = this.props;
		const width = FRAME_WIDTH[UIOptions && UIOptions.format || "sidebar"]
		const baseURLForComp = baseURL || config && config.client && config.client.baseURL || `/${config.name}`
		const baseURLwithTrailingSlash = baseURLForComp + (baseURLForComp.endsWith('/') ? '' : '/')
		const fullScreen = this.state.fullScreen || this.props.UIOptions.format === 'fullscreen';

		return (
			<iframe
				style={{
					width: UIOptions.sandbox ? (fullScreen ? '100%' : width) : '100%',
					maxWidth: '100%',
					height: fullScreen ? '100%' : `${this.state.iFrameHeight}px`,
					overflow: 'scroll',
					border: "none"
				}}
				src={baseURLwithTrailingSlash}
				onLoad={this.iFrameLoaded}
				ref={this.setIFrame}
			/>
		)
	}
}
